113	    pub async fn next<OC: ObjectClient>(&self, client: &OC) -> Result<Option<LookedUp>, InodeError> {
114	        if let Some(readded) = self.readded.lock().unwrap().take() {
115	            return Ok(Some(readded));
116	        }
117	
118	        // Loop because the next entry from the [ReaddirIter] may be hidden from the file system,
119	        // if it has an invalid name.
120	        loop {
121	            let next = {
122	                let mut iter = self.iter.lock().await;
