[metadata] {"type": "create", "filePath": "/workspace/repo/mountpoint-s3/src/inode/negative_cache.rs", "content": "//! A cache of negative lookups, i.e. `(parent inode, name)` pairs that are known not to exist
//! remotely.
//!
//! Caching these lets us avoid repeatedly issuing `HeadObject`/`ListObjectsV2` requests for files
//! that don't exist, which is a common access pattern for some workloads (e.g. searching a `PATH`).
//! Entries expire after a TTL and are evicted in least-recently-used order once the cache is full.
//! They are also explicitly removed when the file is later found to exist (for example, by a
//! `readdir` that discovers it), so the next lookup can be served without a new remote request.

use std::time::{Duration, Instant};

use linked_hash_map::LinkedHashMap;

use crate::inode::InodeNo;
use crate::sync::Mutex;

#[derive(Debug)]
pub struct NegativeCache {
    /// Maximum number of entries to retain. When `0`, the cache is disabled.
    capacity: usize,
    /// How long each entry remains valid after being inserted.
    ttl: Duration,
    /// Entries in least-recently-used order (front = oldest), keyed by parent inode and name, with
    /// the value being the instant at which the entry expires.
    entries: Mutex<LinkedHashMap<String, Instant>>,
}

impl NegativeCache {
    pub fn new(capacity: usize, ttl: Duration) -> Self {
        Self {
            capacity,
            ttl,
            entries: Mutex::new(LinkedHashMap::new()),
        }
    }

    /// Build the cache key for a `(parent inode, name)` pair. Names can never contain `/`, so this
    /// encoding is unambiguous.
    fn key(parent_ino: InodeNo, name: &str) -> String {
        format!("{parent_ino}/{name}")
    }

    /// Return whether the given entry is present in the cache and has not expired. A hit refreshes
    /// the entry's recency so that frequently-checked names are less likely to be evicted.
    pub fn contains(&self, parent_ino: InodeNo, name: &str) -> bool {
        if self.capacity == 0 {
            return false;
        }
        let key = Self::key(parent_ino, name);
        let mut entries = self.entries.lock().unwrap();
        match entries.get_refresh(&key) {
            Some(expiry) if *expiry >= Instant::now() => true,
            Some(_) => {
                // The entry has expired, so remove it and report a miss.
                entries.remove(&key);
                false
            }
            None => false,
        }
    }

    /// Remember that the given `(parent inode, name)` pair does not exist remotely.
    pub fn insert(&self, parent_ino: InodeNo, name: &str) {
        if self.capacity == 0 {
            return;
        }
        let key = Self::key(parent_ino, name);
        let expiry = Instant::now() + self.ttl;
        let mut entries = self.entries.lock().unwrap();
        // Remove first so the (re)inserted entry is placed at the back (most-recently-used).
        entries.remove(&key);
        entries.insert(key, expiry);
        while entries.len() > self.capacity {
            entries.pop_front();
        }
    }

    /// Remove the given entry from the cache, if present. Used when we learn that a previously
    /// missing file now exists.
    pub fn remove(&self, parent_ino: InodeNo, name: &str) {
        if self.capacity == 0 {
            return;
        }
        let key = Self::key(parent_ino, name);
        self.entries.lock().unwrap().remove(&key);
    }
}
